import{_ as t,o,c as d,ah as r}from"./chunks/framework.rk_qxSDs.js";const m=JSON.parse('{"title":"Logger Configuration","description":"Options, preset formats and built-in tokens of the logger.","frontmatter":{"title":"Logger Configuration","description":"Options, preset formats and built-in tokens of the logger.","relatedPlugins":[]},"headers":[],"relativePath":"logger/configuration.md","filePath":"logger/configuration.md","lastUpdated":1794916465000}'),a={name:"logger/configuration.md"};function c(n,e,s,i,h,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>logger()</code> takes an options object, or a format followed by an options object: <code>logger(options?)</code> or <code>logger(format, options?)</code>. In the second form, <code>format</code> wins over <code>options.format</code>. Every option is optional.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>format</code></td><td><code>string | Formatter</code></td><td><code>&#39;tiny&#39;</code></td><td>A preset name, a format string or a function that builds the line</td></tr><tr><td><code>skip</code></td><td><code>(event, response) =&gt; boolean</code></td><td>none</td><td>Return <code>true</code> to write no line for the request</td></tr><tr><td><code>write</code></td><td><code>(line: string) =&gt; void</code></td><td><code>console.log</code></td><td>Where each line goes</td></tr><tr><td><code>immediate</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Write the line when the request arrives instead of after the response</td></tr><tr><td><code>tokens</code></td><td><code>Record&lt;string, Token&gt;</code></td><td><code>{}</code></td><td>Extra tokens, merged over the built-in ones</td></tr></tbody></table><h3 id="format" tabindex="-1"><code>format</code> <a class="header-anchor" href="#format" aria-label="Permalink to &quot;`format`&quot;">​</a></h3><p>A preset name, a format string, or a <a href="/logger/helpers#types"><code>Formatter</code></a> function <code>(tokens, event, response) =&gt; string | undefined</code> that returns the line; <code>undefined</code> writes nothing for that request. Any value that is neither a string nor a function falls back to <code>&#39;tiny&#39;</code>.</p><table tabindex="0"><thead><tr><th>Preset</th><th>Format</th></tr></thead><tbody><tr><td><code>tiny</code></td><td><code>:method :url :status :res[content-length] - :response-time ms</code></td></tr><tr><td><code>short</code></td><td><code>:remote-addr :remote-user :method :url HTTP/:http-version :status :res[content-length] - :response-time ms</code></td></tr><tr><td><code>common</code></td><td><code>:remote-addr - :remote-user [:date[clf]] &quot;:method :url HTTP/:http-version&quot; :status :res[content-length]</code></td></tr><tr><td><code>combined</code></td><td><code>:remote-addr - :remote-user [:date[clf]] &quot;:method :url HTTP/:http-version&quot; :status :res[content-length] &quot;:referrer&quot; &quot;:user-agent&quot;</code></td></tr><tr><td><code>dev</code></td><td><code>:method :url :status :response-time ms - :res[content-length]</code>, the status coloured by range: red <code>5xx</code>, yellow <code>4xx</code>, cyan <code>3xx</code>, green <code>2xx</code></td></tr></tbody></table><p><code>common</code> and <code>combined</code> are the Apache common and combined log formats. <code>dev</code> writes ANSI colour codes, so use it for a terminal, not a log file.</p><p>In a format string, a token is <code>:name</code> or <code>:name[arg]</code>, where the name is at least two letters, digits, <code>_</code> or <code>-</code>. Any other text is copied as is. An unknown token, or a token that returns <code>undefined</code>, renders as <code>-</code>. <a href="/logger/recipes#custom-format-and-tokens">Custom Format and Tokens</a> combines both.</p><h3 id="skip" tabindex="-1"><code>skip</code> <a class="header-anchor" href="#skip" aria-label="Permalink to &quot;`skip`&quot;">​</a></h3><p>Called before the line is formatted, with the event and the <code>Response</code>; return <code>true</code> to write nothing. The response is <code>undefined</code> with <code>immediate</code>, and when the logger received none (see <a href="/logger/#default-behaviour">Default Behaviour</a>). <a href="/logger/recipes#skip-requests">Skip Requests</a> skips health checks and successful responses.</p><h3 id="write" tabindex="-1"><code>write</code> <a class="header-anchor" href="#write" aria-label="Permalink to &quot;`write`&quot;">​</a></h3><p>Receives each line, without a trailing newline. An error it throws is swallowed, so a failing log sink does not fail the request. <a href="/logger/recipes#write-to-a-file">Write to a File</a> appends to a file stream.</p><h3 id="immediate" tabindex="-1"><code>immediate</code> <a class="header-anchor" href="#immediate" aria-label="Permalink to &quot;`immediate`&quot;">​</a></h3><p>Writes the line when the request reaches the logger, before any route runs. There is no <code>Response</code> yet, so <code>:status</code> and <code>:res[*]</code> render <code>-</code> and <code>:response-time</code> is close to <code>0</code>. Use it to see requests that never finish.</p><h3 id="tokens" tabindex="-1"><code>tokens</code> <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;`tokens`&quot;">​</a></h3><p>Extra tokens, <code>(event, response, arg) =&gt; string | undefined</code>, where <code>arg</code> is the text in brackets. They are merged over the built-in tokens, so they add names and can replace a built-in one.</p><table tabindex="0"><thead><tr><th>Token</th><th>Renders</th></tr></thead><tbody><tr><td><code>:method</code></td><td>HTTP method</td></tr><tr><td><code>:url</code></td><td>Path and query string of the request URL</td></tr><tr><td><code>:status</code></td><td>Response status code</td></tr><tr><td><code>:response-time[digits]</code></td><td>Milliseconds since the logger handler started, with <code>digits</code> decimals (default <code>3</code>)</td></tr><tr><td><code>:total-time[digits]</code></td><td>Same as <code>:response-time</code></td></tr><tr><td><code>:date[format]</code></td><td>Current time: <code>web</code> (default, <code>toUTCString()</code>), <code>iso</code> (<code>toISOString()</code>) or <code>clf</code> (<code>10/Oct/2000:13:55:36 +0000</code>, UTC)</td></tr><tr><td><code>:remote-addr</code></td><td>Client address from routup&#39;s <code>getRequestIP()</code>, which follows the app&#39;s <code>trustProxy</code> option</td></tr><tr><td><code>:remote-user</code></td><td>User name from an <code>Authorization: Basic</code> header</td></tr><tr><td><code>:user-agent</code></td><td><code>User-Agent</code> header</td></tr><tr><td><code>:referrer</code></td><td><code>Referer</code> header, or <code>Referrer</code></td></tr><tr><td><code>:http-version</code></td><td><code>httpVersion</code> of the request when the runtime sets one, otherwise <code>1.1</code>; a Web <code>Request</code> has none, so it is usually <code>1.1</code></td></tr><tr><td><code>:req[name]</code></td><td>Request header <code>name</code></td></tr><tr><td><code>:res[name]</code></td><td>Response header <code>name</code></td></tr><tr><td><code>:pid</code></td><td>Process id, <code>0</code> where <code>process</code> does not exist</td></tr></tbody></table><p>Every token renders <code>-</code> when its value is missing.</p>',19)])])}const p=t(a,[["render",c]]);export{m as __pageData,p as default};
